import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { openClockProbe, compareClocks } from './zhiliao-a2-clock-probe-20260912.mjs';

const repo = 'D:/ClaudeProjects/ai_acknowladge';
const sourcePath = fileURLToPath(import.meta.url);
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const source = fs.readFileSync(sourcePath, 'utf8');
const moduleSource = fs.readFileSync(new URL('./zhiliao-a2-clock-probe-20260912.mjs', import.meta.url), 'utf8');
const { runDocker, runProcess, cleanDockerEnvironment } = await import(pathToFileURL(path.join(repo, 'scripts/demo-verification-utils.mjs')));
const { verifyDemoProxyTimeouts } = await import(pathToFileURL(path.join(repo, 'scripts/verify-demo-proxy-timeouts.mjs')));
const env = cleanDockerEnvironment();
const docker = args => runDocker(args, {env, timeoutMs: 15000});
const inputNames = {
  recovery: 'docs/验收证据/story-2-2-wsl-recovery-2026-09-12T09-22-02-992Z.json',
  channel: 'docs/验收证据/story-2-2-root-channel-audit-2026-09-12T09-33-17-334Z.json',
  clock_gate: 'docs/验收证据/story-2-2-normal-clock-2026-09-12T09-35-59-307Z.json',
};
const inputs = Object.fromEntries(Object.entries(inputNames).map(([key, name]) => [key, JSON.parse(fs.readFileSync(path.join(repo, name), 'utf8'))]));
const report = {
  story: '2.2', recorded_at: new Date().toISOString(), status: 'failed',
  scope: '重启后的正常计时门槛通过后，在本次内核启动周期仅运行一次原四场景；不暂停 chronyd，不写时钟参数。',
  source_file: path.basename(sourcePath), source_sha256: sha(source), maintenance_source: source,
  clock_probe_module: moduleSource, clock_probe_module_sha256: sha(moduleSource),
  inputs: Object.fromEntries(Object.entries(inputNames).map(([key, name]) => [key, {path: name, sha256: sha(fs.readFileSync(path.join(repo, name)))}])),
  signals_sent: [], clock_writes: [], chronyd_maintenance: 'not_needed',
  clock_monitor: {interval_ms: 30000, observations: [], samples: []}, proxy: {status: 'not_run'},
  limitations: ['原网络 20 项为重启前环境证据，不替代新内核周期或最终主机网络验证。', '本次不证明长期计时问题已永久修复，不关闭目标主机、业务卷配额、HTTPS 或镜像发布门槛。'],
};
const evidencePath = path.join(repo, 'docs/验收证据/story-2-2-post-restart-a2-' + report.recorded_at.replace(/[:.]/g, '-') + '.json');
const livePath = sourcePath.replace(/\.mjs$/, '.live.json');
if (fs.existsSync(evidencePath) || fs.existsSync(livePath)) throw new Error('记录已存在');
const events = [];
function progress(event) {
  const item = {at: new Date().toISOString(), ...event};
  events.push(item);
  fs.writeFileSync(livePath, JSON.stringify({...report, events}, null, 2) + '\n');
  console.log(JSON.stringify(item));
}
const boot = () => runProcess('wsl.exe', ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'cat', '/proc/sys/kernel/random/boot_id'], {env, timeoutMs: 15000});
async function containers() {
  const ids = (await docker(['ps', '-a', '--no-trunc', '--format', '{{.ID}}'])).split(/\r?\n/).filter(Boolean);
  if (!ids.length) return [];
  const format = '{"id":{{json .Id}},"name":{{json .Name}},"image":{{json .Image}},"status":{{json .State.Status}},"exit_code":{{json .State.ExitCode}},"started_at":{{json .State.StartedAt}},"finished_at":{{json .State.FinishedAt}},"restart_policy":{{json .HostConfig.RestartPolicy}},"mounts":{{json .Mounts}},"networks":{{json .NetworkSettings.Networks}}}';
  return (await docker(['container', 'inspect', '--format', format, ...ids])).split(/\r?\n/).filter(Boolean).map(line => {
    const row = JSON.parse(line);
    row.mounts.sort((a, b) => a.Destination.localeCompare(b.Destination));
    row.networks = Object.keys(row.networks ?? {}).sort();
    return row;
  }).sort((a, b) => a.id.localeCompare(b.id));
}
let beforeContainers, beforeFiles, probe, timer;
let monitoring = Promise.resolve();
let lastSample;
try {
  if (inputs.recovery.status !== 'restored' || !inputs.recovery.preservation.passed || inputs.channel.status !== 'passed' || inputs.clock_gate.status !== 'passed' || inputs.clock_gate.intervals.length !== 2 || inputs.clock_gate.intervals.some(item => !item.passed)) throw new Error('重启、控制通道或计时前提未通过');
  report.boot_id_before = await boot();
  if (report.boot_id_before !== inputs.recovery.after.boot_id || report.boot_id_before !== inputs.channel.identity.boot_id) throw new Error('内核启动周期已变化');
  report.baseline_commit = await runProcess('git', ['rev-parse', 'HEAD'], {env});
  if (report.baseline_commit !== inputs.recovery.baseline_commit) throw new Error('Git 基线发生变化');
  beforeContainers = await containers();
  if (JSON.stringify(beforeContainers) !== JSON.stringify(inputs.recovery.after.containers)) throw new Error('既有容器元数据发生变化');
  const fileNames = new Set(inputs.recovery.before.files.map(item => item.path));
  for (const name of fs.readdirSync(path.join(repo, 'docs/验收证据')).filter(name => /^story-2-2-.*\.json$/.test(name))) fileNames.add('docs/验收证据/' + name);
  beforeFiles = [...fileNames].sort().map(name => ({path: name, sha256: sha(fs.readFileSync(path.join(repo, name)))}));
  for (const [name, image] of Object.entries(inputs.recovery.images)) {
    const actual = await docker(['image', 'inspect', '--format', '{{.Id}}', image.reference]);
    if (actual !== image.id) throw new Error('本地镜像变化：' + name);
  }
  const probeSource = inputs.clock_gate.python_probe;
  if (sha(probeSource) !== inputs.clock_gate.python_probe_sha256) throw new Error('只读探针源码哈希不一致');
  probe = openClockProbe(probeSource, repo);
  await probe.sample();
  lastSample = await probe.endpoint();
  progress({stage: 'preflight_passed', containers: beforeContainers.length, files: beforeFiles.length, boot_id: report.boot_id_before});
  timer = setInterval(() => {
    monitoring = monitoring.then(async () => {
      const sample = await probe.endpoint();
      const interval = compareClocks(lastSample, sample);
      report.clock_monitor.observations.push(interval);
      lastSample = sample;
      progress({stage: 'readonly_clock_monitor', within_one_percent: interval.passed, tick: sample.guest.timex.tick_us,
        maximum_error_percent: Math.max(...Object.values(interval.clocks).flatMap(value => [Math.abs(value.relative_error_lower), Math.abs(value.relative_error_upper)])) * 100});
    }).catch(error => { report.clock_monitor.error = error.message; progress({stage: 'readonly_clock_monitor_failed', error: error.message}); });
  }, 30000);
  report.proxy_started_at = new Date().toISOString();
  const proxy = await verifyDemoProxyTimeouts({port: 3343}, {onProgress: event => progress({stage: 'proxy', ...event})});
  report.proxy = {status: proxy.report.status, exit_code: proxy.exitCode,
    evidence: path.relative(repo, proxy.evidencePath).replaceAll('\\', '/'), sha256: sha(fs.readFileSync(proxy.evidencePath)),
    cleanup: proxy.report.cleanup, scenarios: proxy.report.scenarios.map(item => ({name: item.name, passed: item.passed, elapsed_seconds: item.elapsedSeconds, idle_seconds: item.idle_seconds}))};
  report.status = proxy.exitCode === 0 ? 'passed' : 'failed';
} catch (error) { report.error = error.message; }
finally {
  clearInterval(timer);
  await monitoring;
  if (probe) { report.clock_monitor.samples = probe.samples; report.clock_monitor.probe_exit = await probe.close(); }
  if (beforeContainers && beforeFiles) {
    try {
      const after = await containers();
      report.preservation = {
        containers: beforeContainers.map(row => { const current = after.find(item => item.id === row.id); const changed = Object.keys(row).filter(key => JSON.stringify(row[key]) !== JSON.stringify(current?.[key])); return {id: row.id, name: row.name, unchanged: !changed.length, changed_fields: changed}; }),
        new_container_ids: after.filter(row => !beforeContainers.some(item => item.id === row.id)).map(row => row.id),
        files: beforeFiles.map(row => ({path: row.path, sha256_before: row.sha256, sha256_after: sha(fs.readFileSync(path.join(repo, row.path)))})),
      };
      report.preservation.passed = !report.preservation.new_container_ids.length && report.preservation.containers.every(row => row.unchanged) && report.preservation.files.every(row => row.sha256_before === row.sha256_after);
      if (!report.preservation.passed) report.status = 'failed';
    } catch (error) { report.preservation = {passed: false, error: error.message}; report.status = 'failed'; }
  }
  try { report.boot_id_after = await boot(); if (report.boot_id_after !== report.boot_id_before) report.status = 'failed'; }
  catch (error) { report.boot_check_error = error.message; report.status = 'failed'; }
  report.events = events;
  report.finished_at = new Date().toISOString();
  fs.writeFileSync(evidencePath, JSON.stringify(report, null, 2) + '\n', {flag: 'wx'});
  progress({stage: 'finished', status: report.status, evidence: path.relative(repo, evidencePath).replaceAll('\\', '/'), preservation: report.preservation?.passed});
}
process.exitCode = report.status === 'passed' ? 0 : 1;

